import { createLedger, transfer, getBalance, resetSnapshotCache } from './src/index.js'

// Scenario 1: stale cache lets an overdraft through
{
  resetSnapshotCache()
  const ledger = createLedger()
  ledger.append({ type: 'credit', account: 'alice', amountCents: 10000, ts: 1, id: 'fund' })
  transfer(ledger, 'alice', 'bob', 8000, {}) // alice now has 2000
  const read = getBalance(ledger, 'alice')
  const folded = ledger.fold().alice
  console.log('S1 getBalance(alice) =', read, '| fold(alice) =', folded, '| equal:', read === folded)
  try {
    transfer(ledger, 'alice', 'bob', 3000, {})
    console.log('S1 second transfer DID NOT throw; fold =', ledger.fold(), '| alice negative?', ledger.fold().alice < 0)
  } catch (e) {
    console.log('S1 second transfer threw:', e.message)
  }
}

// Scenario 2: cache is a global singleton shared across ledgers
{
  resetSnapshotCache()
  const a = createLedger()
  a.append({ type: 'credit', account: 'alice', amountCents: 100, ts: 1, id: 'a1' })
  getBalance(a, 'alice') // populates global cache with ledger a's fold
  const b = createLedger()
  b.append({ type: 'credit', account: 'bob', amountCents: 200, ts: 1, id: 'b1' })
  const readB = getBalance(b, 'bob')
  const foldedB = b.fold().bob
  console.log('S2 getBalance(bob) =', readB, '| fold(bob) =', foldedB, '| equal:', readB === foldedB)
}

/**
 * Balance snapshot cache, kept per ledger. Folding the full stream on every
 * read is expensive, so the full snapshot is recomputed at most once every
 * REFRESH_EVERY events; when the stream has only advanced a little since the
 * snapshot, the cached balances are brought up to date incrementally from the
 * events the snapshot has not seen yet. Because every read applies any unseen
 * events before answering, the returned balance always equals the value
 * obtained by folding the current event stream directly.
 */
const REFRESH_EVERY = 8

let caches = new WeakMap()

export function getBalance(ledger, account) {
  const count = ledger.eventCount()
  let cache = caches.get(ledger)
  if (cache === undefined || count >= cache.atCount + REFRESH_EVERY) {
    cache = { atCount: count, balances: ledger.fold() }
    caches.set(ledger, cache)
  } else if (count > cache.atCount) {
    for (const event of ledger.eventsFrom(cache.atCount)) {
      const current = cache.balances[event.account] ?? 0
      cache.balances[event.account] = current + (event.type === 'credit' ? event.amountCents : -event.amountCents)
    }
    cache.atCount = count
  }
  return cache.balances[account] ?? 0
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

