import { createLedger, transfer, getBalance, resetSnapshotCache, createRebateHook } from './src/index.js'

let failures = 0
const fail = (msg) => { failures++; console.log('FAIL:', msg) }

function check(ledger, label) {
  const folded = ledger.fold()
  const accounts = new Set([...Object.keys(folded), 'ghost'])
  let sum = 0
  for (const acct of accounts) {
    const g = getBalance(ledger, acct)
    const f = folded[acct] ?? 0
    if (g !== f) fail(`${label}: getBalance(${acct}) ${g} != fold ${f}`)
    sum += g
  }
  if (Object.values(folded).some((v) => v < 0)) fail(`${label}: negative balance in fold ${JSON.stringify(folded)}`)
  return { sum, expected: Object.values(folded).reduce((a, b) => a + b, 0) }
}

// 1) Interleaved ledgers + random transfers, with occasional direct appends
resetSnapshotCache()
const L = [createLedger(), createLedger(), createLedger()]
for (const l of L) l.append({ type: 'credit', account: 'alice', amountCents: 100000, ts: 0, id: 'fund' })
for (let i = 0; i < 3000; i++) {
  const l = L[i % 3]
  const amt = 1 + (i % 997)
  try {
    transfer(l, 'alice', 'bob', amt, {})
  } catch {
    // expected occasionally: insufficient funds
  }
  if (i % 50 === 0) {
    // batch appends to exercise the full-refold threshold
    l.append({ type: 'credit', account: 'bulk', amountCents: i, ts: i, id: `bulk-${i}` })
  }
  const { sum, expected } = check(l, `iter${i}`)
  if (sum !== expected) fail(`iter${i}: getBalance sum ${sum} != fold sum ${expected}`)
}

// 2) Rebate chains at several rates
for (const rate of [1, 3, 7, 10, 33, 50, 99]) {
  resetSnapshotCache()
  const l = createLedger()
  l.append({ type: 'credit', account: 'alice', amountCents: 50000, ts: 0, id: 'fund' })
  l.append({ type: 'credit', account: 'bob', amountCents: 50000, ts: 0, id: 'fund' })
  const hook = createRebateHook(l, rate)
  try {
    transfer(l, 'alice', 'bob', 20000, { onSettled: hook })
  } catch (e) {
    fail(`rate ${rate}: rebate chain threw ${e.message}`)
  }
  const { sum, expected } = check(l, `rate${rate}`)
  if (sum !== expected) fail(`rate ${rate}: sum mismatch`)
}

// 3) Conservation invariant on a fresh transfer sequence
resetSnapshotCache()
{
  const l = createLedger()
  l.append({ type: 'credit', account: 'a', amountCents: 777, ts: 0, id: 'f' })
  l.append({ type: 'credit', account: 'b', amountCents: 123, ts: 0, id: 'g' })
  const start = Object.values(l.fold()).reduce((x, y) => x + y, 0)
  for (let i = 0; i < 500; i++) {
    try { transfer(l, i % 2 ? 'a' : 'b', i % 2 ? 'b' : 'a', (i % 50) + 1, {}) } catch { /* expected */ }
  }
  const end = Object.values(l.fold()).reduce((x, y) => x + y, 0)
  if (start !== end) fail(`conservation: ${start} != ${end}`)
  if (Object.values(l.fold()).some((v) => v < 0)) fail('conservation run: negative balance')
}

console.log(failures === 0 ? 'ALL INVARIANT CHECKS PASSED' : `${failures} FAILURES`)
